48	// toolResultJSON is the compact result object inlined into tool_use blocks.
49	type toolResultJSON struct {
50		Output     string              `json:"output"`
51		Status     string              `json:"status"`
52		File       *toolResultFileJSON `json:"file,omitempty"`
53		MatchCount int                 `json:"matchCount,omitempty"`
54	}
