68	// Compact converts a full.jsonl transcript into the condensed transcript.jsonl format.
69	//
70	// The output format puts version, agent, and cli_version on every line,
71	// merges streaming assistant fragments with the same message ID, and inlines
72	// tool results into the preceding assistant's tool_use blocks:
73	//
74	//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"user","ts":"...","content":"..."}
75	//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"assistant","ts":"...","id":"msg_xxx","content":[{"type":"text","text":"..."},{"type":"tool_use","id":"...","name":"...","input":{...},"result":{"output":"...","status":"..."}}]}
76	func Compact(content []byte, opts MetadataFields) ([]byte, error) {
77		truncated := transcript.SliceFromLine(content, opts.StartLine)
78		if truncated == nil {
79			truncated = []byte{}
80		}
81	
82		if isOpenCodeFormat(truncated) {
83			return compactOpenCode(truncated, opts)
84		}
85	
86		return compactJSONL(truncated, opts)
87	}
88	
89	// droppedTypes are JSONL entry types that carry no parser-relevant data.
90	var droppedTypes = map[string]bool{
91		"progress":              true,
92		"file-history-snapshot": true,
93		"queue-operation":       true,
94		"system":                true,
95	}
96	
97	// userAliases maps JSONL type/role values to the canonical "user" kind.
98	// Covers Claude Code ("user", "human") and Cursor ("user" via "role" field).
99	var userAliases = map[string]bool{
100		transcript.TypeUser: true,
101		"human":             true,
102	}
103	
104	// normalizeKind returns the canonical entry kind ("user" or "assistant") for a
105	// JSONL transcript line. It checks the "type" field, then falls back to "role".
106	// Returns "" for unrecognised or dropped entries.
107	func normalizeKind(raw map[string]json.RawMessage) string {
108		kind := unquote(raw["type"])
109		if kind == "" {
110			kind = unquote(raw["role"])
111		}
112	
113		if droppedTypes[kind] {
114			return ""
115		}
116		if userAliases[kind] {
117			return transcript.TypeUser
118		}
119		if kind == transcript.TypeAssistant {
120			return transcript.TypeAssistant
121		}
122		return ""
123	}
124	
125	// parsedEntry is an intermediate representation of a JSONL line used during
126	// the two-pass compact conversion.
127	type parsedEntry struct {
128		kind         string // "user" or "assistant"
129		ts           json.RawMessage
130		id           string            // message ID (assistant only)
131		userID       string            // prompt ID (user only, e.g. Claude's promptId)
132		inputTokens  int               // API input tokens (assistant only)
133		outputTokens int               // API output tokens (assistant only)
134		content      json.RawMessage   // stripped assistant content array, or nil
135		userText     string            // extracted user text
136		userImages   []json.RawMessage // image blocks from user messages
137		toolResults  []toolResultEntry // user tool_result entries
138	}
139	
140	// compactJSONL converts JSONL transcripts (Claude Code, Cursor) into the
141	// transcript.jsonl format.
142	func compactJSONL(content []byte, opts MetadataFields) ([]byte, error) {
143		base := newTranscriptLine(opts)
144	
145		// Pass 1: parse all lines into intermediate entries.
146		entries, err := parseJSONLEntries(content)
147		if err != nil {
148			return nil, err
149		}
150	
151		// Pass 2: merge and emit.
152		var result []byte
153		for i := 0; i < len(entries); i++ {
154			e := entries[i]
155	
156			switch e.kind {
157			case transcript.TypeAssistant:
158				// Merge consecutive assistant entries with the same message ID.
159				merged := e
160				for i+1 < len(entries) && entries[i+1].kind == transcript.TypeAssistant && entries[i+1].id == e.id {
161					i++
162					merged = mergeAssistantEntries(merged, entries[i])
163				}
164	
165				// Look ahead for user tool_result entries to inline.
166				if i+1 < len(entries) && entries[i+1].kind == transcript.TypeUser && hasToolResults(entries[i+1]) {
167					userEntry := entries[i+1]
168					merged = inlineToolResults(merged, userEntry)
169					i++ // consume the user tool_result entry
170	
171					// If the consumed user entry also had text or image content, emit it
172					// as a separate user line after the assistant.
173					if userEntry.userText != "" || len(userEntry.userImages) > 0 {
174						emitAssistant(&result, base, merged)
175						emitUser(&result, base, userEntry)
176						continue
177					}
178				}
179	
180				if isEmptyContentArray(merged.content) {
181					continue
182				}
183	
184				emitAssistant(&result, base, merged)
185	
186			case transcript.TypeUser:
187				// User entries that are purely tool results were already consumed
188				// by the assistant look-ahead above. If we reach one here it was
189				// not preceded by an assistant with a matching tool_use, so emit
190				// it only if it has text or image content.
191				if hasToolResults(e) && e.userText == "" && len(e.userImages) == 0 {
192					continue
193				}
194				emitUser(&result, base, e)
195			}
196		}
197	
198		return result, nil
199	}
200	
201	func emitAssistant(result *[]byte, base transcriptLine, e parsedEntry) {
202		line := base
203		line.Type = transcript.TypeAssistant
204		line.TS = e.ts
205		line.ID = e.id
206		line.InputTokens = e.inputTokens
207		line.OutputTokens = e.outputTokens
208		line.Content = e.content
209		appendLine(result, line)
210	}
211	
212	func emitUser(result *[]byte, base transcriptLine, e parsedEntry) {
213		var blocks []json.RawMessage
214	
215		// Text block (with optional prompt ID).
216		if e.userText != "" || len(e.userImages) == 0 {
217			b, err := json.Marshal(userTextBlock{ID: e.userID, Text: e.userText})
218			if err != nil {
219				return
220			}
221			blocks = append(blocks, b)
222		}
223	
224		// Image blocks passed through verbatim.
225		blocks = append(blocks, e.userImages...)
226	
227		contentJSON, err := json.Marshal(blocks)
228		if err != nil {
229			return
230		}
231	
232		line := base
233		line.Type = transcript.TypeUser
234		line.TS = e.ts
235		line.Content = contentJSON
236		appendLine(result, line)
237	}
238	
239	// appendLine marshals a transcriptLine and appends it (with newline) to result.
240	func appendLine(result *[]byte, line transcriptLine) {
241		b, err := json.Marshal(line)
242		if err != nil {
243			return
244		}
245		*result = append(*result, b...)
246		*result = append(*result, '\n')
247	}
248	
249	// parseJSONLEntries parses all JSONL lines into intermediate entries,
250	// filtering dropped types and malformed lines.
251	func parseJSONLEntries(content []byte) ([]parsedEntry, error) {
252		reader := bufio.NewReader(bytes.NewReader(content))
253		var entries []parsedEntry
254	
255		for {
256			lineBytes, err := reader.ReadBytes('\n')
257			if err != nil && err != io.EOF {
258				return nil, fmt.Errorf("reading JSONL line: %w", err)
259			}
260	
261			if len(bytes.TrimSpace(lineBytes)) > 0 {
262				if e, ok := parseLine(lineBytes); ok {
263					entries = append(entries, e)
264				}
265			}
266	
267			if err == io.EOF {
268				break
269			}
270		}
271	
272		return entries, nil
273	}
274	
275	// parseLine converts a single JSONL line into a parsedEntry.
276	// Returns ok=false for dropped/malformed lines.
277	func parseLine(lineBytes []byte) (parsedEntry, bool) {
278		var raw map[string]json.RawMessage
279		if err := json.Unmarshal(lineBytes, &raw); err != nil {
280			return parsedEntry{}, false
281		}
282	
283		kind := normalizeKind(raw)
284		if kind == "" {
285			return parsedEntry{}, false
286		}
287	
288		e := parsedEntry{
289			kind: kind,
290			ts:   raw["timestamp"],
291		}
292	
293		msg := parseMessage(raw)
294	
295		switch kind {
296		case transcript.TypeAssistant:
297			if msg != nil {
298				e.id = unquote(msg["id"])
299				if contentRaw, ok := msg["content"]; ok {
300					e.content = stripAssistantContent(contentRaw)
301				}
302				e.inputTokens, e.outputTokens = extractUsageTokens(msg)
303			}
304	
305		case transcript.TypeUser:
306			e.userID = unquote(raw["promptId"])
307			if msg != nil {
308				if contentRaw, ok := msg["content"]; ok {
309					uc := extractUserContent(contentRaw)
310					e.userText = uc.text
311					e.userImages = uc.images
312					e.toolResults = uc.toolResults
313				}
314			}
315			// Enrich tool results with metadata from toolUseResult.
316			if turRaw, ok := raw["toolUseResult"]; ok {
317				var tur map[string]json.RawMessage
318				if json.Unmarshal(turRaw, &tur) == nil {
319					e.toolResults = enrichToolResults(e.toolResults, tur)
320				}
321			}
322		}
323	
324		return e, true
325	}
326	
327	// mergeAssistantEntries combines two assistant entries with the same message ID.
328	// Content arrays are concatenated; the later timestamp and token counts win
329	// (streaming fragments report cumulative usage, so the last fragment is final).
330	func mergeAssistantEntries(a, b parsedEntry) parsedEntry {
331		merged := a
332		merged.ts = b.ts
333		if b.inputTokens > 0 {
334			merged.inputTokens = b.inputTokens
335		}
336		if b.outputTokens > 0 {
337			merged.outputTokens = b.outputTokens
338		}
339	
340		var aBlocks, bBlocks []json.RawMessage
341		_ = json.Unmarshal(a.content, &aBlocks) //nolint:errcheck // best-effort merge
342		_ = json.Unmarshal(b.content, &bBlocks) //nolint:errcheck // best-effort merge
343		all := append(aBlocks, bBlocks...)      //nolint:gocritic // intentional append to new slice
344		if data, err := json.Marshal(all); err == nil {
345			merged.content = data
346		}
347	
348		return merged
349	}
350	
351	// inlineToolResults adds "result" fields to matching tool_use blocks in the
352	// assistant entry's content, using outputs from user tool_result entries.
353	func inlineToolResults(assistant, user parsedEntry) parsedEntry {
354		var blocks []map[string]json.RawMessage
355		if json.Unmarshal(assistant.content, &blocks) != nil || len(blocks) == 0 {
356			return assistant
357		}
358	
359		for _, tr := range user.toolResults {
360			// Find the tool_use block matching this tool_use_id.
361			idx := -1
362			for i := len(blocks) - 1; i >= 0; i-- {
363				if unquote(blocks[i]["type"]) == transcript.ContentTypeToolUse {
364					if tr.toolUseID == "" || unquote(blocks[i]["id"]) == tr.toolUseID {
365						idx = i
366						break
367					}
368				}
369			}
370			// No matching tool_use block: do not attach a result to unrelated content.
371			if idx == -1 {
372				continue
373			}
374	
375			blocks[idx]["result"] = buildToolResult(tr)
376		}
377	
378		if data, err := json.Marshal(blocks); err == nil {
379			assistant.content = data
380		}
381	
382		return assistant
383	}
384	
385	// buildToolResult constructs the compact result object for a tool_use block,
386	// including optional rich metadata (file, matchCount) when available.
387	func buildToolResult(tr toolResultEntry) json.RawMessage {
388		r := toolResultJSON{
389			Output:     tr.output,
390			Status:     "success",
391			MatchCount: tr.matchCount,
392		}
393		if tr.isError {
394			r.Status = "error"
395		}
396		if tr.file != nil {
397			r.File = &toolResultFileJSON{
398				FilePath: tr.file.filePath,
399				NumLines: tr.file.numLines,
400			}
401		}
402		b, err := json.Marshal(r)
403		if err != nil {
404			return nil
405		}
406		return b
407	}
408	
409	// extractUsageTokens extracts input_tokens and output_tokens from a Claude
410	// message's "usage" object. Returns (0, 0) if usage is absent or malformed.
411	func extractUsageTokens(msg map[string]json.RawMessage) (inputTokens, outputTokens int) {
412		usageRaw, ok := msg["usage"]
413		if !ok {
414			return 0, 0
415		}
416		var usage struct {
417			InputTokens  int `json:"input_tokens"`
418			OutputTokens int `json:"output_tokens"`
419		}
420		if json.Unmarshal(usageRaw, &usage) != nil {
421			return 0, 0
422		}
423		return usage.InputTokens, usage.OutputTokens
424	}
425	
426	// isEmptyContentArray returns true if raw is a JSON empty array (`[]`).
427	func isEmptyContentArray(raw json.RawMessage) bool {
428		var arr []json.RawMessage
429		return json.Unmarshal(raw, &arr) == nil && len(arr) == 0
430	}
431	
432	func hasToolResults(e parsedEntry) bool {
433		return len(e.toolResults) > 0
434	}
435	
436	type toolResultEntry struct {
437		toolUseID string
438		output    string
439		isError   bool
440		// Rich metadata extracted from toolUseResult (optional).
441		file       *toolResultFile // Read/Edit: file path and line count
442		matchCount int             // Grep: number of matching files
443	}
444	
445	// toolResultFile carries structured file metadata from Read/Edit tool results.
446	type toolResultFile struct {
447		filePath string
448		numLines int // 0 if not available (e.g. Edit results)
449	}
450	
451	// enrichToolResults extracts structured metadata from a toolUseResult envelope
452	// and attaches it to the corresponding tool result entries.
453	//
454	// Claude Code's toolUseResult has different shapes per tool:
455	//   - Bash:  {stdout, stderr, interrupted, ...}
456	//   - Read:  {type:"text", file:{filePath, numLines, content, ...}}
457	//   - Grep:  {numFiles, numLines, filenames, content, mode}
458	//   - Edit:  {filePath, oldString, newString, structuredPatch, ...}
459	func enrichToolResults(results []toolResultEntry, tur map[string]json.RawMessage) []toolResultEntry {
460		// Bash-style: stdout provides the output text.
461		if stdout := unquote(tur["stdout"]); stdout != "" {
462			switch len(results) {
463			case 0:
464				// Keep compatibility with transcripts that only include toolUseResult.
465				results = append(results, toolResultEntry{output: stdout})
466			case 1:
467				results[0].output = stdout
468			}
469		}
470	
471		// Read-style: file object with filePath and numLines.
472		if fileRaw, ok := tur["file"]; ok {
473			var file struct {
474				FilePath string `json:"filePath"`
475				NumLines int    `json:"numLines"`
476			}
477			if json.Unmarshal(fileRaw, &file) == nil && file.FilePath != "" {
478				applyToSingleResult(results, func(tr *toolResultEntry) {
479					tr.file = &toolResultFile{filePath: file.FilePath, numLines: file.NumLines}
480				})
481			}
482		}
483	
484		// Edit-style: top-level filePath.
485		if filePath := unquote(tur["filePath"]); filePath != "" {
486			applyToSingleResult(results, func(tr *toolResultEntry) {
487				// Edit results don't have numLines.
488				tr.file = &toolResultFile{filePath: filePath}
489			})
490		}
491	
492		// Grep-style: numFiles as match count.
493		if numFilesRaw, ok := tur["numFiles"]; ok {
494			var n int
495			if json.Unmarshal(numFilesRaw, &n) == nil && n > 0 {
496				applyToSingleResult(results, func(tr *toolResultEntry) {
497					tr.matchCount = n
498				})
499			}
500		}
501	
502		return results
503	}
504	
505	// applyToSingleResult applies fn to the first (and expected only) tool result.
506	// toolUseResult is a single-tool envelope, so this is only meaningful when
507	// there's exactly one result entry.
508	func applyToSingleResult(results []toolResultEntry, fn func(*toolResultEntry)) {
509		if len(results) == 1 {
510			fn(&results[0])
511		}
512	}
513	
514	// parseMessage extracts and parses the "message" field from a JSONL transcript
515	// line. All JSONL agents nest content inside a "message" object.
516	func parseMessage(raw map[string]json.RawMessage) map[string]json.RawMessage {
517		msgRaw, ok := raw["message"]
518		if !ok {
519			return nil
520		}
521		var msg map[string]json.RawMessage
522		if json.Unmarshal(msgRaw, &msg) == nil {
523			return msg
524		}
525		return nil
526	}
527	
528	// userContent holds the extracted parts of a user message content array.
529	type userContent struct {
530		text        string
531		images      []json.RawMessage
532		toolResults []toolResultEntry
533	}
534	
535	// extractUserContent separates user message content into text, images, and tool_result entries.
536	// IDE context tags (e.g. <user_query>, <ide_opened_file>) are stripped from user text.
537	func extractUserContent(contentRaw json.RawMessage) userContent {
538		var str string
539		if json.Unmarshal(contentRaw, &str) == nil {
540			return userContent{text: textutil.StripIDEContextTags(str)}
541		}
542	
543		var blocks []json.RawMessage
544		if json.Unmarshal(contentRaw, &blocks) != nil {
545			return userContent{}
546		}
547	
548		var uc userContent
549	
550		for _, blockRaw := range blocks {
551			var block map[string]json.RawMessage
552			if json.Unmarshal(blockRaw, &block) != nil {
553				continue
554			}
555			blockType := unquote(block["type"])
556	
557			switch blockType {
558			case "tool_result":
559				var isErr bool
560				if raw, ok := block["is_error"]; ok {
561					_ = json.Unmarshal(raw, &isErr) //nolint:errcheck // best-effort
562				}
563				uc.toolResults = append(uc.toolResults, toolResultEntry{
564					toolUseID: unquote(block["tool_use_id"]),
565					output:    unquote(block["content"]),
566					isError:   isErr,
567				})
568	
569			case "image":
570				uc.images = append(uc.images, blockRaw)
571	
572			case transcript.ContentTypeText:
573				stripped := textutil.StripIDEContextTags(unquote(block[transcript.ContentTypeText]))
574				if stripped != "" {
575					uc.text += stripped + "\n\n"
576				}
577			}
578		}
579	
580		uc.text = strings.TrimSpace(uc.text)
581		return uc
582	}
583	
584	func stripAssistantContent(contentRaw json.RawMessage) json.RawMessage {
585		var str string
586		if json.Unmarshal(contentRaw, &str) == nil {
587			return contentRaw
588		}
589	
590		var blocks []map[string]json.RawMessage
591		if json.Unmarshal(contentRaw, &blocks) != nil {
592			return contentRaw
593		}
594	
595		result := make([]map[string]json.RawMessage, 0, len(blocks))
596		for _, block := range blocks {
597			blockType := unquote(block["type"])
598	
599			if blockType == "thinking" || blockType == "redacted_thinking" {
600				continue
601			}
602	
603			if blockType == transcript.ContentTypeToolUse {
604				stripped := make(map[string]json.RawMessage)
605				copyField(stripped, block, "type")
606				copyField(stripped, block, "id")
607				copyField(stripped, block, "name")
608				copyField(stripped, block, "input")
609				result = append(result, stripped)
610				continue
611			}
612	
613			result = append(result, block)
614		}
615	
616		b, err := json.Marshal(result)
617		if err != nil {
618			return contentRaw
619		}
620		return b
621	}
622	
623	// copyField copies a single key from src to dst if it exists.
624	func copyField(dst, src map[string]json.RawMessage, key string) {
625		if v, ok := src[key]; ok {
626			dst[key] = v
627		}
628	}
629	
630	// unquote JSON-decodes a raw message as a string. Returns "" on failure.
631	func unquote(raw json.RawMessage) string {
632		var s string
633		if json.Unmarshal(raw, &s) == nil {
634			return s
635		}
636		return ""
637	}
