13	// --- OpenCode format support ---
14	//
15	// OpenCode transcripts are a single JSON object (not JSONL):
16	//
17	//	{"info":{...},"messages":[{"info":{"role":"user","time":{...}},"parts":[...]}, ...]}
18	//
19	// Parts use "type" values: "text", "tool", "step-start", "step-finish".
20	// Tool parts store the tool name in "tool" (string) and call details in "state".
21	
22	// isOpenCodeFormat checks whether content is a single JSON object with the
23	// OpenCode session shape (top-level "info" and "messages" keys).
24	func isOpenCodeFormat(content []byte) bool {
25		trimmed := bytes.TrimSpace(content)
26		if len(trimmed) == 0 || trimmed[0] != '{' {
27			return false
28		}
29		// Quick structural check: unmarshal just enough to detect the keys.
30		var probe struct {
31			Info     *json.RawMessage `json:"info"`
32			Messages *json.RawMessage `json:"messages"`
33		}
34		if json.Unmarshal(trimmed, &probe) != nil {
35			return false
36		}
37		return probe.Info != nil && probe.Messages != nil
38	}
39	
40	// openCodeMessage mirrors the OpenCode message structure for unmarshaling.
41	type openCodeMessage struct {
42		Info  openCodeMessageInfo          `json:"info"`
43		Parts []map[string]json.RawMessage `json:"parts"`
44	}
45	
46	type openCodeMessageInfo struct {
47		ID     string            `json:"id"`
48		Role   string            `json:"role"`
49		Time   openCodeMsgTime   `json:"time"`
50		Tokens *openCodeMsgToken `json:"tokens"`
51	}
52	
53	type openCodeMsgTime struct {
54		Created   int64 `json:"created"`
55		Completed int64 `json:"completed"`
56	}
57	
58	type openCodeMsgToken struct {
59		Input  int `json:"input"`
60		Output int `json:"output"`
61	}
62	
63	// compactOpenCode converts a full OpenCode session JSON into transcript lines.
64	func compactOpenCode(content []byte, opts MetadataFields) ([]byte, error) {
65		var session struct {
66			Messages []openCodeMessage `json:"messages"`
67		}
68		if err := json.Unmarshal(bytes.TrimSpace(content), &session); err != nil {
69			return nil, fmt.Errorf("parsing opencode session: %w", err)
70		}
71	
72		base := newTranscriptLine(opts)
73		var result []byte
74	
75		for _, msg := range session.Messages {
76			ts := msToTimestamp(msg.Info.Time.Created)
77	
78			switch msg.Info.Role {
79			case transcript.TypeUser:
80				emitOpenCodeUser(&result, base, msg, ts)
81			case transcript.TypeAssistant:
82				emitOpenCodeAssistant(&result, base, msg, ts)
83			}
84		}
85	
86		return result, nil
87	}
88	
89	func emitOpenCodeUser(result *[]byte, base transcriptLine, msg openCodeMessage, ts json.RawMessage) {
90		var blocks []json.RawMessage
91	
92		for _, part := range msg.Parts {
93			if unquote(part["type"]) != transcript.ContentTypeText {
94				continue
95			}
96			text := textutil.StripIDEContextTags(unquote(part[transcript.ContentTypeText]))
97			if text == "" {
98				continue
99			}
100			tb := userTextBlock{Text: text}
101			if id := part["id"]; id != nil {
102				_ = json.Unmarshal(id, &tb.ID) //nolint:errcheck // best-effort
103			}
104			b, err := json.Marshal(tb)
105			if err != nil {
106				continue
107			}
108			blocks = append(blocks, b)
109		}
110	
111		contentJSON, err := json.Marshal(blocks)
112		if err != nil {
113			return
114		}
115	
116		line := base
117		line.Type = transcript.TypeUser
118		line.TS = ts
119		line.Content = contentJSON
120		appendLine(result, line)
121	}
122	
123	func emitOpenCodeAssistant(result *[]byte, base transcriptLine, msg openCodeMessage, ts json.RawMessage) {
124		content := make([]map[string]json.RawMessage, 0, len(msg.Parts))
125	
126		for _, part := range msg.Parts {
127			partType := unquote(part["type"])
128	
129			switch partType {
130			case transcript.ContentTypeText:
131				b, err := json.Marshal(transcript.ContentTypeText)
132				if err != nil {
133					continue
134				}
135				content = append(content, map[string]json.RawMessage{
136					"type": b,
137					"text": part[transcript.ContentTypeText],
138				})
139			case "tool":
140				toolBlock := make(map[string]json.RawMessage)
141				b, err := json.Marshal(transcript.ContentTypeToolUse)
142				if err != nil {
143					continue
144				}
145				toolBlock["type"] = b
146				if callID := part["callID"]; callID != nil {
147					toolBlock["id"] = callID
148				}
149				if toolName := part["tool"]; toolName != nil {
150					toolBlock["name"] = toolName
151				}
152				if stateRaw := part["state"]; stateRaw != nil {
153					var state map[string]json.RawMessage
154					if json.Unmarshal(stateRaw, &state) == nil {
155						if inp := state["input"]; inp != nil {
156							toolBlock["input"] = inp
157						}
158						toolBlock["result"] = openCodeToolResult(state)
159					}
160				}
161				content = append(content, toolBlock)
162			}
163		}
164	
165		contentJSON, err := json.Marshal(content)
166		if err != nil {
167			return
168		}
169	
170		line := base
171		line.Type = transcript.TypeAssistant
172		line.TS = ts
173		line.ID = msg.Info.ID
174		line.Content = contentJSON
175		if msg.Info.Tokens != nil {
176			line.InputTokens = msg.Info.Tokens.Input
177			line.OutputTokens = msg.Info.Tokens.Output
178		}
179		appendLine(result, line)
180	}
181	
182	// openCodeToolResult builds the compact {"output":"...","status":"success"|"error"}
183	// object from an OpenCode tool state map.
184	func openCodeToolResult(state map[string]json.RawMessage) json.RawMessage {
185		r := toolResultJSON{
186			Output: unquote(state["output"]),
187			Status: "success",
188		}
189		if s := unquote(state["status"]); s != "" && s != "completed" {
190			r.Status = "error"
191		}
192		b, err := json.Marshal(r)
193		if err != nil {
194			return nil
195		}
196		return b
197	}
198	
199	// msToTimestamp converts a Unix millisecond timestamp to an RFC3339 JSON string.
200	func msToTimestamp(ms int64) json.RawMessage {
201		if ms == 0 {
202			return nil
203		}
204		t := time.UnixMilli(ms).UTC()
205		b, err := json.Marshal(t.Format(time.RFC3339Nano))
206		if err != nil {
207			return nil
208		}
209		return b
210	}
