574	func assertFixtureTransform(t *testing.T, opts MetadataFields, inputPath, expectedPath string) {
575		t.Helper()
576	
577		input, err := os.ReadFile(inputPath)
578		if err != nil {
579			t.Fatalf("failed to read fixture %q: %v", inputPath, err)
580		}
581	
582		expected, err := os.ReadFile(expectedPath)
583		if err != nil {
584			t.Fatalf("failed to read expected output %q: %v", expectedPath, err)
585		}
586	
587		result, err := Compact(input, opts)
