594	func nonEmptyLines(data []byte) []string {
595		var lines []string
596		for _, line := range strings.Split(string(data), "\n") {
597			if strings.TrimSpace(line) != "" {
598				lines = append(lines, line)
599			}
600		}
601		return lines
602	}
603	
604	// assertJSONLines compares actual output lines against expected JSON strings,
605	// using semantic JSON equality (order-independent for object keys).
606	func assertJSONLines(t *testing.T, actual []byte, expected []string) {
607		t.Helper()
608	
609		actualLines := nonEmptyLines(actual)
610	
611		if len(expected) == 0 && len(actualLines) == 0 {
612			return
613		}
614	
615		if len(actualLines) != len(expected) {
616			t.Fatalf("line count mismatch: got %d, want %d\nactual:\n%s", len(actualLines), len(expected), string(actual))
617		}
618	
619		for i := range expected {
620			var got, want interface{}
621			if err := json.Unmarshal([]byte(actualLines[i]), &got); err != nil {
622				t.Fatalf("line %d: failed to parse actual JSON: %v\nline: %s", i, err, actualLines[i])
623			}
624			if err := json.Unmarshal([]byte(expected[i]), &want); err != nil {
625				t.Fatalf("line %d: failed to parse expected JSON: %v\nline: %s", i, err, expected[i])
626			}
627			if !reflect.DeepEqual(got, want) {
628				prettyGot, _ := json.MarshalIndent(got, "", "  ")   //nolint:errcheck,errchkjson // test helper, marshal of interface{} is best-effort
629				prettyWant, _ := json.MarshalIndent(want, "", "  ") //nolint:errcheck,errchkjson // test helper, marshal of interface{} is best-effort
630				t.Errorf("line %d mismatch:\ngot:\n%s\nwant:\n%s", i, prettyGot, prettyWant)
631			}
632		}
633	}
